window.AUTH=window.AUTH||{};window.AUTH["21-12"]={"d":"21-12","id":"2021/21-12","n":"Federal Election Commission v. Ted Cruz for Senate","briefs":[{"k":"petitioner","label":"Brief of appellant Federal Election Commission","date":"2021-11-15","url":"https://www.supremecourt.gov/DocketPDF/21/21-12/199971/20211115161335789_21-12tsUnitedStates.pdf","side":"pet","n":55},{"k":"respondent","label":"Brief of appellees Ted Cruz For Senate, et al.","date":"2021-12-15","url":"https://www.supremecourt.gov/DocketPDF/21/21-12/205134/20211215112123841_21-12%20Brief%20of%20Appellees.pdf","side":"res","n":60},{"k":"reply","label":"Reply of appellant Federal Election Commission","date":"2022-01-06","url":"https://www.supremecourt.gov/DocketPDF/21/21-12/207574/20220106153559466_Cruz%20Reply%20-%20Final.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us1r30_o759.pdf","tr":true,"items":[{"t":"case","label":"Arizona Free Enterprise Club’s Freedom Club PAC v. Bennett","cite":"564 U.S. 721","y":2011,"id":"2010/10-238","sc":1,"op":4,"sum":"The Court held that the Arizona campaign finance law linking public financing for candidates to the amount spent by their opponents violated the First Amendment's protection of political speech.","sumSrc":"Oyez","by":{"0":"27, 33, 40","1":"41, 42, 43, 44, 46, 47"}},{"t":"case","label":"Bluman v. FEC","cite":"766 F. Supp. 2d 1","y":2011,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/766/1/","by":{"0":"19"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"op":13,"ar":4,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"passim","1":"1, 17, 40, 42, 45","2":"11, 12, 14, 18"}},{"t":"case","label":"California v. Texas","cite":"141 S. Ct. 2104","y":2021,"id":"2020/19-840","sc":1,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17, 18, 19, 21","1":"18, 19, 20","2":"7"}},{"t":"case","label":"Christian Legal Society Chapter v. Martinez","cite":"561 U.S. 661","y":2010,"id":"2009/08-1371","sc":1,"sum":"The Court held that a college's mandate requiring all officially-recognized student organizations be inclusive and welcoming to all students did not violate a group of Christian students' First Amendment rights when the college refused to recognize a student group that required all members to sign a statement of Christian beliefs for membership.","sumSrc":"Oyez","by":{"0":"15","2":"3"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"op":3,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"0":"26","1":"51"}},{"t":"case","label":"Clapper v. Amnesty International USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"op":1,"ar":2,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"0":"21","1":"33, 34","2":"8"}},{"t":"case","label":"Clark v. Community for Creative Non-Violence","cite":"468 U.S. 288","y":1984,"id":"1983/82-1998","sc":1,"sum":"In a 7-to-2 decision, the Court held that the regulations did not violate the First Amendment. The Court noted that expression is subject to reasonable time, place, and manner restrictions, and that the manner of the protest was at odds with the government's interest in maintaining the condition of the parks.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Clements v. Fashing","cite":"457 U.S. 957","y":1982,"id":"1981/80-1290","sc":1,"sum":"The judgment is reversed. 631 F. 2d 731, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Clingman v. Beaver","cite":"544 U.S. 581","y":2005,"id":"2004/04-37","sc":1,"sum":"The Court held that Oklahoma's semiclosed primary system did not violate the right to freedom of association and that any burden it imposed was minor and justified by legitimate state interests. The Court noted that not every electoral law burdening associational rights was subject to strict scrutiny.","sumSrc":"Oyez","by":{"0":"26","2":"11"}},{"t":"case","label":"Cyan, Inc. v. Beaver County Employees Retirement Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"op":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"0":"18","1":"21"}},{"t":"case","label":"Davis v. FEC","cite":"554 U.S. 724","y":2008,"id":"2007/07-320","sc":1,"op":3,"sum":"Although all nine Justices agreed that Davis had standing to argue his case before the Court, only a 5-4 majority held that the contribution limits violated the First Amendment. In his majority opinion, Justice Samuel Alito noted that the Court had never upheld the constitutionality of a law imposing different contribution limits for candidates competing against one another.","sumSrc":"Oyez","by":{"0":"26, 28, 47","1":"6, 41, 42, 43, 47","2":"18"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Services, Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"0":"43, 44"}},{"t":"case","label":"FCC v. Prometheus Radio Project","cite":"141 S. Ct. 1150","y":2021,"id":"2020/19-1231","sc":1,"sum":"The Federal Communications Commission’s 2017 decision to repeal or modify three of its media ownership rules was not arbitrary or capricious for purposes of the Administrative Procedure Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"43"}},{"t":"case","label":"FEC v. National Right to Work Committee","cite":"459 U.S. 197","y":1982,"id":"1982/81-1506","sc":1,"op":2,"ar":3,"sum":"The Federal Election Campaign Act of 1971, 2 U. S. C. §441b(a), prohibits corporations and labor unions from making contributions or expenditures in connection with federal elections. The section, however, permits some participation by unions and corporations in the federal electoral process by allowing these organizations to establish and pay the expenses of \"separate segregated funds\" which may be used for …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"FEC v. O’Donnell","cite":"209 F. Supp. 3d 727","y":2016,"court":"D. Del.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/209/727/","by":{"0":"34"}},{"t":"case","label":"FW/PBS, Inc. v. City of Dallas","cite":"493 U.S. 215","y":1990,"id":"1989/87-2012","sc":1,"sum":"The judgment is affirmed in part, reversed in part, and vacated in part, and the cases are remanded. 837 F. 2d 1298, affirmed in part, reversed in part, vacated in part, and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts III and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Ferre v. State ex rel. Reno","cite":"478 So. 2d 1077","y":1985,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/478/1077/","by":{"0":"35, 42"}},{"t":"case","label":"Frisby v. Schultz","cite":"487 U.S. 474","y":1988,"id":"1987/87-168","sc":1,"sum":"The Court held that since the street constituted a traditional public forum, the ban must satisfy strict standards in order to remain. Since the ban is \"content neutral,\" \"leaves open ample alternative channels of communication,\" and serves a \"significant government interest,\" the Court ruled that it passed the strict standards and could remain.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Furnco Construction Corp. v. Waters","cite":"438 U.S. 567","y":1978,"id":"1977/77-369","sc":1,"sum":"The Court of Appeals erred in its treatment of the nature of the evidence necessary to rebut a prima facie case under McDonnell Douglas, and in substituting its own judgment as to the proper hiring practices for an employer who claims its hiring practices do not violate Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"op":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"0":"18","1":"21"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":2,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"10, 12, 14, 25","1":"38","2":"2, 11"}},{"t":"case","label":"McConnell v. FEC","cite":"540 U.S. 93","y":2003,"id":"2003/02-1674","sc":1,"op":2,"sum":"The Court found that regulations in the Campaign Finance Reform Act of 2002 did not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"passim","1":"23, 24, 35"}},{"t":"case","label":"McCullen v. Coakley","cite":"573 U.S. 464","y":2014,"id":"2013/12-1168","sc":1,"op":1,"sum":"The Court ruled that the Massachusetts legislature violated the freedom of speech protections of the First Amendment when it created a 35-foot buffer around the entrances, exits and driveways of abortion clinics where political activity was prohibited.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"McCutcheon v. FEC","cite":"572 U.S. 185","y":2014,"id":"2013/12-536","sc":1,"op":11,"ar":3,"sum":"The Court ruled that the two-year aggregate campaign contribution limit of the Bipartisan Campaign Reform Act was unconstitutional.","sumSrc":"Oyez","by":{"0":"41, 44","1":"47, 48, 51, 52, 54, 55","2":"16, 17"}},{"t":"case","label":"Moose Lodge No. 107 v. Irvis","cite":"407 U.S. 163","y":1972,"id":"1971/70-75","sc":1,"sum":"In a 6-to-3 decision, the Court held that the Moose Lodge's refusal to serve food and beverages to Irvis because he was black did not violate the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"18","1":"21"}},{"t":"case","label":"Natural Resources Defense Council, Inc. v. United States Food & Drug Administration","cite":"710 F.3d 71","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/710/71/","by":{"0":"24"}},{"t":"case","label":"Nixon v. Shrink Missouri Government PAC","cite":"528 U.S. 377","y":2000,"id":"1999/98-963","sc":1,"op":5,"sum":"The Court held that Buckley is the authority for comparable state regulation and, but that the federal limits approved in Buckley, with or without adjustment for inflation, do not define the scope of permissible state limitations.","sumSrc":"Oyez","by":{"0":"27, 31, 33, 42, 43"}},{"t":"case","label":"Pennsylvania v. New Jersey","cite":"426 U.S. 660","y":1976,"id":"1975/68_orig","sc":1,"op":1,"sum":"Under the New Jersey Transportation Benefits Tax Act, New Jersey does not tax its residents' domestic income, but does tax nonresidents' New Jersey-derived income and imposes an equivalent tax on residents' income earned outside the State except that such income is exempted to the extent it is taxed by the State in which it is earned. The New Hampshire Commuters Tax was held unconstitutional in Austin v. New …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","1":"35, 36","2":"8"}},{"t":"case","label":"R. A. V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"op":1,"sum":"The Court found a Minnesota ordinance violated the First Amendment because the ordinance was overly broad in the content-based speech it prohibited.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Randall v. Sorrell","cite":"548 U.S. 230","y":2006,"id":"2005/04-1528","sc":1,"op":5,"sum":"The opinion by Justice Stephen Breyer held that the Court should let stand the Buckley decision and its invalidation of expenditure limits. Vermont's argument that such limits prevent candidates from spending too much time fund-raising was deemed irrelevant because it was \"perfectly obvious\" and would not have changed the result in Buckley .","sumSrc":"Oyez","by":{"0":"44","1":"46"}},{"t":"case","label":"Shapiro v. McManus","cite":"577 U.S. 39","y":2015,"id":"2015/14-990","sc":1,"sum":"The Court held that a claim covered by the Three-Judge Court Act must be heard by a three-judge panel.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"op":1,"ar":2,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17, 25","2":"7"}},{"t":"case","label":"United States v. Richardson","cite":"418 U.S. 166","y":1974,"id":"1973/72-885","sc":1,"sum":"The Court held that Richardson did not have standing to sue. Using the two-pronged standing test of Flast v. Cohen (1968), Chief Justice Burger found that there was no \"logical nexus between the status asserted [by Richardson as a taxpayer] and the claim sought to be adjudicated.\" It was clear to Burger that Richardson was not \"a proper and appropriate party to invoke federal judicial power\" on this issue.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Wilkinson v. Jones","cite":"876 F. Supp. 916","y":1995,"court":"W.D. Ky.","url":"https://www.courtlistener.com/c/F.%20Supp./876/916/","op":2,"by":{"0":"39"}},{"t":"case","label":"Williams-Yulee v. Florida Bar","cite":"575 U.S. 433","y":2015,"id":"2014/13-1499","sc":1,"sum":"The Court held that a rule prohibiting judicial candidates from personally soliciting campaign funds does not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"26, 41, 43, 46, 48","2":"16"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"9, 10, 18, 20, 22","2":"6, 8"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"passim","2":"11, 20, 21"}},{"t":"law","label":"Pub. L. No. 107-155","url":"https://www.govinfo.gov/link/plaw/107/public/155","by":{"0":"2","2":"18"}},{"t":"law","label":"Pub. L. No. 92-225","url":"https://www.govinfo.gov/link/statute/86/3","by":{"0":"2"}},{"t":"usc","label":"52 U.S.C. § 30106","url":"https://www.law.cornell.edu/uscode/text/52/30106","by":{"0":"2"}},{"t":"usc","label":"52 U.S.C. § 30114","url":"https://www.law.cornell.edu/uscode/text/52/30114","subs":["(b)(2)"],"stext":{"head":"§30114. Use of contributed amounts for certain purposes","paras":[[0,"(a) Permitted uses"],[0,"A contribution accepted by a candidate, and any other donation received by an individual as support for activities of the individual as a holder of Federal office, may be used by the candidate or individual—"],[1,"(1) for otherwise authorized expenditures in connection with the campaign for Federal office of the candidate or individual;"],[1,"(2) for ordinary and necessary expenses incurred in connection with duties of the individual as a holder of Federal office;"],[1,"(3) for contributions to an organization described in section 170(c) of title 26;"],[1,"(4) for transfers, without limitation, to a national, State, or local committee of a political party;"],[1,"(5) for donations to State and local candidates subject to the provisions of State law; or"],[1,"(6) for any other lawful purpose unless prohibited by subsection (b) of this section."],[0,"(b) Prohibited use"],[0,"(1) In general"],[1,"A contribution or donation described in subsection (a) shall not be converted by any person to personal use."],[0,"(2) Conversion"],[1,"For the purposes of paragraph (1), a contribution or donation shall be considered to be converted to personal use if the contribution or amount is used to fulfill any commitment, obligation, or expense of a person that would exist irrespective of the candidate's election campaign or individual's duties as a holder of Federal office, including—"],[2,"(A) a home mortgage, rent, or utility payment;"],[2,"(B) a clothing purchase;"],[2,"(C) a noncampaign-related automobile expense;"],[2,"(D) a country club membership;"],[2,"(E) a vacation or other noncampaign-related trip;"],[2,"(F) a household food item;"],[2,"(G) a tuition payment;"],[2,"(H) admission to a sporting event, concert, theater, or other form of entertainment not associated with an election campaign; and"],[2,"(I) dues, fees, and other payments to a health club or recreational facility."],[0,"(c) Restrictions on use of campaign funds for flights on noncommercial aircraft"],[0,"(1) In general"],[1,"Notwithstanding any other provision of this Act, a candidate for election for Federal office (other than a candidate who is subject to paragraph (2)), or any authorized committee of such a candidate, may not make any expenditure for a flight on an aircraft unless—"],[2,"(A) the aircraft is operated by an air carrier or commercial operator certificated by the Federal Aviation Administration and the flight is required to be conducted under air carrier safety rules, or, in the case of travel which is abroad, by an air carrier or commercial operator certificated by an appropriate foreign civil aviation authority and the flight is required to be conducted under air carrier safety rules; or"],[2,"(B) the candidate, the authorized committee, or other political committee pays to the owner, lessee, or other person who provides the airplane the pro rata share of the fair market value of such flight (as determined by dividing the fair market value of the normal and usual charter fare or rental charge for a comparable plane of comparable size by the number of candidates on the flight) within a commercially reasonable time frame after the date on which the flight is taken."],[0,"(2) House candidates"],[1,"Notwithstanding any other provision of this Act, in the case of a candidate for election for the office of Representative in, or Delegate or Resident Commissioner to, the Congress, an authorized committee and a leadership PAC of the candidate may not make any expenditure for a flight on an aircraft unless—"],[2,"(A) the aircraft is operated by an air carrier or commercial operator certificated by the Federal Aviation Administration and the flight is required to be conducted under air carrier safety rules, or, in the case of travel which is abroad, by an air carrier or commercial operator certificated by an appropriate foreign civil aviation authority and the flight is required to be conducted under air carrier safety rules; or"],[2,"(B) the aircraft is operated by an entity of the Federal government or the government of any State."],[0,"(3) Exception for aircraft owned or leased by candidate"],[0,"(A) In general"],[2,"Paragraphs (1) and (2) do not apply to a flight on an aircraft owned or leased by the candidate involved or an immediate family member of the candidate (including an aircraft owned by an entity that is not a public corporation in which the candidate or an immediate family member of the candidate has an ownership interest), so long as the candidate does not use the aircraft more than the candidate's or immediate family member's proportionate share of ownership allows."],[0,"(B) Immediate family member defined"],[2,"In this subparagraph (A), the term \"immediate family member\" means, with respect to a candidate, a father, mother, son, daughter, brother, sister, husband, wife, father-in-law, or mother-in-law."],[0,"(4) Leadership PAC defined"],[1,"In this subsection, the term \"leadership PAC\" has the meaning given such term in section 30104(i)(8)(B) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/30114?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§30114. Use of contributed amounts for certain purposes","tname":"Voting and Elections","by":{"0":"34"}},{"t":"usc","label":"52 U.S.C. § 30116","url":"https://www.law.cornell.edu/uscode/text/52/30116","subs":["(a)","(c)","(i)"],"stext":{"head":"§30116. Limitations on contributions and expenditures","paras":[[0,"(a) Dollar limits on contributions"],[0,"(1) Except as provided in subsection (i) and section 30117 of this title, no person shall make contributions—"],[1,"(A) to any candidate and his authorized political committees with respect to any election for Federal office which, in the aggregate, exceed $2,000;"],[1,"(B) to the political committees established and maintained by a national political party, which are not the authorized political committees of any candidate, in any calendar year which, in the aggregate, exceed $25,000, or, in the case of contributions made to any of the accounts described in paragraph (9), exceed 300 percent of the amount otherwise applicable under this subparagraph with respect to such calendar year;"],[1,"(C) to any other political committee (other than a committee described in subparagraph (D)) in any calendar year which, in the aggregate, exceed $5,000; or"],[1,"(D) to a political committee established and maintained by a State committee of a political party in any calendar year which, in the aggregate, exceed $10,000."],[0,"(2) No multicandidate political committee shall make contributions—"],[1,"(A) to any candidate and his authorized political committees with respect to any election for Federal office which, in the aggregate, exceed $5,000;"],[1,"(B) to the political committees established and maintained by a national political party, which are not the authorized political committees of any candidate, in any calendar year, which, in the aggregate, exceed $15,000, or, in the case of contributions made to any of the accounts described in paragraph (9), exceed 300 percent of the amount otherwise applicable under this subparagraph with respect to such calendar year; or"],[1,"(C) to any other political committee in any calendar year which, in the aggregate, exceed $5,000."],[0,"(3) During the period which begins on January 1 of an odd-numbered year and ends on December 31 of the next even-numbered year, no individual may make contributions aggregating more than—"],[1,"(A) $37,500, in the case of contributions to candidates and the authorized committees of candidates;"],[1,"(B) $57,500, in the case of any other contributions, of which not more than $37,500 may be attributable to contributions to political committees which are not political committees of national political parties."],[0,"(4) The limitations on contributions contained in paragraphs (1) and (2) do not apply to transfers between and among political committees which are national, State, district, or local committees (including any subordinate committee thereof) of the same political party. For purposes of paragraph (2), the term \"multicandidate political committee\" means a political committee which has been registered under section 30103 of this title for a period of not less than 6 months, which has received contributions from more than 50 persons, and, except for any State political party organization, has made contributions to 5 or more candidates for Federal office."],[0,"(5) For purposes of the limitations provided by paragraph (1) and paragraph (2), all contributions made by political committees established or financed or maintained or controlled by any corporation, labor organization, or any other person, including any parent, subsidiary, branch, division, department, or local unit of such corporation, labor organization, or any other person, or by any group of such persons, shall be considered to have been made by a single political committee, except that (A) nothing in this sentence shall limit transfers between political committees of funds raised through joint fund raising efforts; (B) for purposes of the limitations provided by paragraph (1) and paragraph (2) all contributions made by a single political committee established or financed or maintained or controlled by a national committee of a political party and by a single political committee established or financed or maintained or controlled by the State committee of a political party shall not be considered to have been made by a single political committee; and (C) nothing in this section shall limit the transfer of funds between the principal campaign committee of a candidate seeking nomination or election to a Federal office and the principal campaign committee of that candidate for nomination or election to another Federal office if (i) such transfer is not made when the candidate is actively seeking nomination or election to both such offices; (ii) the limitations contained in this Act on contributions by persons are not exceeded by such transfer; and (iii) the candidate has not elected to receive any funds under chapter 95 or chapter 96 of title 26. In any case in which a corporation and any of its subsidiaries, branches, divisions, departments, or local units, or a labor organization and any of its subsidiaries, branches, divisions, departments, or local units establish or finance or maintain or control more than one separate segregated fund, all such separate segregated funds shall be treated as a single separate segregated fund for purposes of the limitations provided by paragraph (1) and paragraph (2)."],[0,"(6) The limitations on contributions to a candidate imposed by paragraphs (1) and (2) of this subsection shall apply separately with respect to each election, except that all elections held in any calendar year for the office of President of the United States (except a general election for such office) shall be considered to be one election."],[0,"(7) For purposes of this subsection—"],[1,"(A) contributions to a named candidate made to any political committee authorized by such candidate to accept contributions on his behalf shall be considered to be contributions made to such candidate;"],[1,"(B)(i) expenditures made by any person in cooperation, consultation, or concert, with, or at the request or suggestion of, a candidate, his authorized political committees, or their agents, shall be considered to be a contribution to such candidate;"],[1,"(ii) expenditures made by any person (other than a candidate or candidate's authorized committee) in cooperation, consultation, or concert with, or at the request or suggestion of, a national, State, or local committee of a political party, shall be considered to be contributions made to such party committee; and"],[1,"(iii) the financing by any person of the dissemination, distribution, or republication, in whole or in part, of any broadcast or any written, graphic, or other form of campaign materials prepared by the candidate, his campaign committees, or their authorized agents shall be considered to be an expenditure for purposes of this paragraph; and 1"],[1,"(C) if—"],[2,"(i) any person makes, or contracts to make, any disbursement for any electioneering communication (within the meaning of section 30104(f)(3) of this title); and"],[2,"(ii) such disbursement is coordinated with a candidate or an authorized committee of such candidate, a Federal, State, or local political party or committee thereof, or an agent or official of any such candidate, party, or committee;"],[1,"such disbursement or contracting shall be treated as a contribution to the candidate supported by the electioneering communication or that candidate's party and as an expenditure by that candidate or that candidate's party; and"],[1,"(D) contributions made to or for the benefit of any candidate nominated by a political party for election to the office of Vice President of the United States shall be considered to be contributions made to or for the benefit of the candidate of such party for election to the office of President of the United States."],[0,"(8) For purposes of the limitations imposed by this section, all contributions made by a person, either directly or indirectly, on behalf of a particular candidate, including contributions which are in any way earmarked or otherwise directed through an intermediary or conduit to such candidate, shall be treated as contributions from such person to such candidate. The intermediary or conduit shall report the original source and the intended recipient of such contribution to the Commission and to the intended recipient."],[0,"(9) An account described in this paragraph is any of the following accounts:"],[1,"(A) A separate, segregated account of a national committee of a political party (other than a national congressional campaign committee of a political party) which is used solely to defray expenses incurred with respect to a presidential nominating convention (including the payment of deposits) or to repay loans the proceeds of which were used to defray such expenses, or otherwise to restore funds used to defray such expenses, except that the aggregate amount of expenditures the national committee of a political party may make from such account may not exceed $20,000,000 with respect to any single convention."],[1,"(B) A separate, segregated account of a national committee of a political party (including a national congressional campaign committee of a political party) which is used solely to defray expenses incurred with respect to the construction, purchase, renovation, operation, and furnishing of one or more headquarters buildings of the party or to repay loans the proceeds of which were used to defray such expenses, or otherwise to restore funds used to defray such expenses (including expenses for obligations incurred during the 2-year period which ends on December 16, 2014)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/30116?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§30116. Limitations on contributions and expenditures","tname":"Voting and Elections","by":{"0":"2, 3, 3, 45","2":"18, passim"}},{"t":"usc","label":"52 U.S.C. § 30144","url":"https://www.law.cornell.edu/uscode/text/52/30144","stext":{"head":"§30144. Partial invalidity","paras":[[0,"If any provision of this Act, or the application thereof to any person or circumstance, is held invalid, the validity of the remainder of the Act and the application of such provision to other persons and circumstances shall not be affected thereby."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/30144?type=usc&year=mostrecent&link-type=html"},"head":"§30144. Partial invalidity","tname":"Voting and Elections","by":{"0":"45","2":"21"}},{"t":"usc","label":"26 U.S.C. § 5000A","url":"https://www.law.cornell.edu/uscode/text/26/5000A","subs":["(a)"],"by":{"0":"17"}},{"t":"usc","label":"2 U.S.C. § 4725","url":"https://www.law.cornell.edu/uscode/text/2/4725","stext":{"head":"§4725. Gifts and travel","paras":[[0,"(a) Gifts"],[0,"(1) No Member, officer, or employee of the Senate, or the spouse or dependent thereof, shall knowingly accept, directly or indirectly, any gift or gifts in any calendar year aggregating more than the minimal value as established by section 7342(a)(5) of title 5 or $250, whichever is greater 1 from any person, organization, or corporation unless, in an unusual case, a waiver is granted by the Select Committee on Ethics."],[0,"(2) The prohibitions of this subsection do not apply to gifts—"],[1,"(A) from relatives;"],[1,"(B) with a value of $100 or less, as adjusted under section 13104(a)(2)(A) of title 5; or"],[1,"(C) of personal hospitality of an individual."],[0,"(3) For purposes of this subsection—"],[1,"(A) the term \"gift\" means a payment, subscription, advance, forbearance, rendering, or deposit of money, services, or anything of value, including food, lodging, transportation, or entertainment, and reimbursement for other than necessary expenses, unless consideration of equal or greater value is received, but does not include (1) a political contribution otherwise reported as required by law, (2) a loan made in a commercially reasonable manner (including requirements that the loan be repaid and that a reasonable rate of interest be paid), (3) a bequest, inheritance, or other transfer at death, (4) a bona fide award presented in recognition of public service and available to the general public, (5) a reception at which the Member, officer, or employee is to be honored, provided such individual receives no other gifts that exceed the restrictions in this rule, other than a suitable memento, (6) meals or beverages consumed or enjoyed, provided the meals or beverages are not consumed or enjoyed in connection with a gift of overnight lodging, or (7) anything of value given to a spouse or dependent of a reporting individual by the employer of such spouse or dependent in recognition of the service provided by such spouse or dependent; and"],[1,"(B) the term \"relative\" has the same meaning given to such term in section 13101(16) of title 5."],[0,"(4) If a Member, officer, or employee, after exercising reasonable diligence to obtain the information necessary to comply with this rule, unknowingly accepts a gift described in paragraph (1) such Member, officer, or employee shall, upon learning of the nature of the gift and its source, return the gift or, if it is not possible to return the gift, reimburse the donor for the value of the gift."],[0,"(5)(A) Notwithstanding the provisions of this subsection, a Member, officer, or employee of the Senate may participate in a program, the principal objective of which is educational, sponsored by a foreign government or a foreign educational or charitable organization involving travel to a foreign country paid for by that foreign government or organization if such participation is not in violation of any law and if the select 2 Committee on Ethics has determined that participation in such program by Members, officers, or employees of the Senate is in the interests of the Senate and the United States."],[0,"(B) Any Member who accepts an invitation to participate in any such program shall notify the Select Committee in writing of his acceptance. A Member shall also notify the Select Committee in writing whenever he has permitted any officer or employee whom he supervises to participate in any such program. The chairman of the Select Committee shall place in the Congressional Record a list of all individuals,3 participating, the supervisors of such individuals where applicable; 4 and the nature and itinerary of such program."],[0,"(C) No Member, officer, or employee may accept funds in connection with participation in a program permitted under subparagraph (A) if such funds are not used for necessary food, lodging, transportation, and related expenses of the Member, officer, or employee."],[0,"(b) Limits on domestic and foreign travel by Members and staff of Senate"],[0,"The term \"necessary expenses\", with respect to limits on domestic and foreign travel by Members and staff of the Senate, means reasonable expenses for food, lodging, or transportation which are incurred by a Member, officer, or employee of the Senate in connection with services provided to (or participation in an event sponsored by) the organization which provides reimbursement for such expenses or which provides the food, lodging, or transportation directly. Necessary expenses do not include the provision of food, lodging, or transportation, or the payment for such expenses, for a continuous period in excess of 3 days exclusive of travel time within the United States or 7 days exclusive of travel time outside of the United States unless such travel is approved by the Committee on Ethics as necessary for participation in a conference, seminar, meeting or similar matter. Necessary expenses do not include the provision of food, lodging, or transportation, or the payment for such expenses, for anyone accompanying a Member, officer, or employee of the Senate, other than the spouse or child of such Member, officer, or employee of the Senate or one Senate employee acting as an aide to a Member."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/4725?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4725. Gifts and travel","tname":"The Congress","by":{"0":"34"}},{"t":"usc","label":"5 U.S.C. § 7342","url":"https://www.law.cornell.edu/uscode/text/5/7342","by":{"0":"34"}},{"t":"usc","label":"5 U.S.C. § 7351","url":"https://www.law.cornell.edu/uscode/text/5/7351","by":{"0":"34"}},{"t":"usc","label":"5 U.S.C. § 7353","url":"https://www.law.cornell.edu/uscode/text/5/7353","by":{"0":"34"}},{"t":"reg","label":"5 C.F.R. § 2635.204","url":"https://www.ecfr.gov/current/title-5/section-2635.204","by":{"0":"34"}},{"t":"reg","label":"Price Index Adjustments for Contribution and Expenditure Limitations and Lobbyist Bundling Disclosure Threshold, 82 Fed. Reg. 10,904","url":"https://www.govinfo.gov/link/fr/82/10904","by":{"0":"3"}},{"t":"case","label":"A.L.A. Schechter Poultry Corp. v. United States","cite":"295 U.S. 495","y":1935,"id":"1900-1940/295us495","sc":1,"sum":"The Court held that the legislative branch cannot delegate to the President the authority to regulate industries without also providing standards or rules for doing so.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Allen v. Wright","cite":"468 U.S. 737","y":1984,"id":"1983/81-757","sc":1,"sum":"The Court found that the circumstances involved in this case did not warrant federal-court adjudication.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"American Power & Light Co. v. SEC","cite":"329 U.S. 90","y":1946,"id":"scdb/1946-007","sc":1,"sum":"that the orders were authorized by § 11 (b) (2) and that the section as so applied is constitutional. Pp. 96, 121.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Anderson v. Spear","cite":"356 F.3d 651","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/356/651/","by":{"1":"7, 40, 48"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Broadrick v. Oklahoma","cite":"413 U.S. 601","y":1973,"id":"1972/71-1639","sc":1,"sum":"Section 818 of the Oklahoma statute is not unconstitutional on its face. CSC v. Letter Carriers, ante, p. 548.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45, 54, 55","2":"20, 21"}},{"t":"case","label":"Brown v. Board of Education","cite":"347 U.S. 483","y":1954,"id":"1940-1955/347us483","sc":1,"sum":"The Court decided that the \"separate but equal\" standards of racial segregation were unconstitutional, paving the way for the Civil Rights Movement and national desegregation.","sumSrc":"Oyez","by":{"1":"31, 32"}},{"t":"case","label":"Carney v. Adams, 592 U.S. ---","cite":"141 S. Ct. 493","y":2020,"id":"2020/19-309","sc":1,"ar":2,"sum":"Because plaintiff Adams has not shown that he was “able and ready” to apply for a judicial vacancy in the imminent future, Gratz v. Bollinger, 539 U. S. 244, 262, he has failed to demonstrate Article III standing to challenge the Delaware Constitution’s political balance requirement for appointments to the State’s major courts.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29"}},{"t":"case","label":"Chicago, Indianapolis, & Louisville Ry. Co. v. Hackett","cite":"228 U.S. 559","y":1913,"id":"scdb/1912-188","sc":1,"sum":"This court has heretofore sustained the constitutionality of-the statute of Indiana of 1893 abolishing as to railroad corporations the defense to actions for personal injuries sustained by employés of negligence of a fellow-servant. Tullís v. Lake Erie Railroad, 175 U. S. 348;, Louis..& Nash. R. R. v. Melton, 218 U. S. 38.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"13, 16"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"op":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"1":"16","2":"5, 6"}},{"t":"case","label":"Collins v. Yellen, 594 U.S. ---","cite":"141 S. Ct. 1761","y":2021,"id":"2020/19-422","sc":1,"op":1,"sum":"Because the Federal Housing Finance Agency (FHFA) did not exceed its authority under the Housing and Economic Recovery Act of 2008 as a conservator of Fannie Mae and Freddie Mac, the anti-injunction provisions of the Recovery Act bar the statutory claim brought by shareholders of those entities; the Recovery Act’s structure, which restricts the President’s power to remove the FHFA Director, violates the separation of powers.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16","2":"5"}},{"t":"case","label":"DOT v. Association of Am. R.R.s","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"sum":"The Court held that for purposes of the validity of metrics and standards, Amtrak is a governmental entity.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Evers v. Dwyer","cite":"358 U.S. 202","y":1958,"id":"1958/382","sc":1,"op":1,"sum":"The record in this case establishes the existence of an actual controversy which should have been adjudicated by the District Court. Pp. 202-204. Reversed and case remanded for further proceedings. Robert L. Carterfor appellants. Walter Chandler, Allison B. Humphreys, Edward P. Russell and Charles M. Crump for appellees.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31","2":"9"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"op":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"12, 13"}},{"t":"case","label":"FEC v. Akins","cite":"524 U.S. 11","y":1998,"id":"1997/96-1590","sc":1,"sum":"The Court held that voters seeking information, to which they believe FECA entitles them, have standing to challenge the FEC's decision not to bring an enforcement action. Because FECA seeks to address the voters' injury, the failure to obtain relevant information, Justice Breyer concluded that the voters had prudential standing.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Financial Oversight & Mgmt. Bd. for P.R. v. Aurelius Inv., LLC, 590 U.S. ---","cite":"140 S. Ct. 1649","y":2020,"id":"2019/18-1334","sc":1,"sum":"A group of cases in which the Court will decide the constitutionality of President Barack Obama’s appointments (without their being confirmed by the Senate) to the oversight board created to help Puerto Rico recover from its substantial indebtedness.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Gundy v. United States, 588 U.S. ---","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17, 18"}},{"t":"case","label":"Havens Realty Corp. v. Coleman","cite":"455 U.S. 363","y":1982,"id":"1981/80-988","sc":1,"op":1,"sum":"Section 804 of the Fair Housing Act of 1968 (Act) makes unlawful various forms of discriminatory housing practices. Section 812(a) authorizes civil actions to enforce §804 and requires that suit be brought within 180 days after the alleged occurrence of a discriminatory practice. A class action for declaratory, injunctive, and monetary relief was brought in Federal District Court against petitioners-Havens Realty …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 31, 37","2":"9"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"J.W. Hampton, Jr., & Co. v. United States","cite":"276 U.S. 394","y":1928,"id":"1900-1940/276us394","sc":1,"sum":"The Court held that Congress, within \"defined limits,\" could vest discretion in Executive officers to make public regulations and direct the details of statutory execution. The Court argued that the same principle that allowed Congress to fix rates in interstate commerce also enabled it to remit to a rate-making body under the control of the Executive branch.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"op":10,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"1":"14, 15"}},{"t":"case","label":"Lichter v. United States","cite":"334 U.S. 742","y":1948,"id":"scdb/1947-108","sc":1,"sum":"1. The Renegotiation Act is constitutional on its face as authority for the recovery by the United States of \"excessive profits\" (less tax credits) realized by private parties in the circumstances of these cases on subcontracts for war goods in time of war with contractors who were also private parties--even in the absence of contractual provisions for the renegotiation of such profits and even as applied to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Louisiana Pub. Serv. Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"op":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 14"}},{"t":"case","label":"Loving v. United States","cite":"517 U.S. 748","y":1996,"id":"1995/94-1966","sc":1,"sum":"The Court held that not only does the Constitution require the aggravating factors of the military's death penalty, but that the President's prescription of the challenged aggravating factors did not violate the separation-of-powers principle.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"MWAA v. Citizens for Abatement of Aircraft Noise, Inc.","cite":"501 U.S. 252","y":1991,"id":"1990/90-906","sc":1,"sum":"An Act of Congress (hereinafter the Transfer Act) authorized the transfer of operating control of Washington National Airport (National) and Dulles International Airport (Dulles) from the federal Department of Transportation to petitioner Metropolitan Washington Airports Authority (MWAA), which was created by a compact between Virginia and the District of Columbia. Both airports are located in the Virginia suburbs …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 17"}},{"t":"case","label":"NBC v. United States","cite":"319 U.S. 190","y":1943,"id":"scdb/1942-051","sc":1,"sum":"1. The regulatory powers of the Federal Communications Commission are not limited to the engineering and technical aspects of radio communication.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"op":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Panama Ref. Co. v. Ryan","cite":"293 U.S. 388","y":1935,"id":"1900-1940/293us388","sc":1,"sum":"Writing for the 8-1 majority, Chief Justice Charles E. Hughes concluded the order was not constitutional. Supreme Court held that in enacting the order, the President subsumed legislative powers that Congress does not have the power to delegate. Congress cannot delegate legislative powers to other branches of government in order to sustain the democratic system of government.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Pierson v. Ray","cite":"386 U.S. 547","y":1967,"id":"1966/79","sc":1,"sum":"Petitioners,t,'members of a group of white and Negro clergymen on a \"prayer pilgrimage\" to promote racial integration, attempted to use a segregated interstate bus terminal waiting room in Jackson, Mississippi, in 1961. They were arrested by respondent policemen and charged with conduct breaching the peace in violation of § 2087.5 of the Mississippi Code which this Court, in 1965, held unconstitutional in Thomas v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Rothstein v. UBS AG","cite":"708 F.3d 82","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/708/82/","by":{"1":"29"}},{"t":"case","label":"Schneider v. Smith","cite":"390 U.S. 17","y":1968,"id":"1967/196","sc":1,"sum":"Appellant applied to the Commandant of the Coast Guard for validation of his merchant mariner's document evidencing his ability to act as a second assistant engineer. Such validation is required by regulations promulgated pursuant to the Magnuson Act, which authorizes the President, if he finds that \"the security of the United States is endangered by... subversive activity,\" to issue regulations \"to safeguard... …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Seila Law LLC v. CFPB, 591 U.S. ---","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"South Bay United Pentecostal Church v. Newsom, 592 U.S. ---","cite":"141 S. Ct. 716","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/716/","sc":1,"by":{"1":"54"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"op":2,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Touby v. United States","cite":"500 U.S. 160","y":1991,"id":"1990/90-6282","sc":1,"sum":"The Court held that the Controlled Substances Act allows the Attorney General to delegate authority to the Drug Enforcement Agency.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Ward v. Rock Against Racism","cite":"491 U.S. 781","y":1989,"id":"1988/88-226","sc":1,"sum":"The Court upheld the ordinance, giving broad deference to the government's interest in maintaining order. As long as \"the means chosen are not substantially broader than necessary to achieve the government's interest,\" a regulation will not be invalidated because a court concludes that the government's interest \"could be adequately served by some less-speech-restrictive alternative.\".","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Warth v. Seldin","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"op":1,"sum":"Whether the rules of standing are considered as aspects of the constitutional requirement that a plaintiff must make out a \"case or controversy\" within the meaning of Art. III, or, apart from such requirement, as prudential limitations on the courts' role in resolving disputes involving \"generalized grievances\" or third parties' legal rights or interests, none of the petitioners has met the threshold requirement of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(C)"],"by":{"1":"13"}},{"t":"usc","label":"18 U.S.C. § 607","url":"https://www.law.cornell.edu/uscode/text/18/607","by":{"1":"21"}},{"t":"usc","label":"52 U.S.C. § 30101","url":"https://www.law.cornell.edu/uscode/text/52/30101","subs":["(9)(A)(i)"],"stext":{"head":"§30101. Definitions","paras":[[0,"When used in this Act:"],[0,"(1) The term \"election\" means—"],[1,"(A) a general, special, primary, or runoff election;"],[1,"(B) a convention or caucus of a political party which has authority to nominate a candidate;"],[1,"(C) a primary election held for the selection of delegates to a national nominating convention of a political party; and"],[1,"(D) a primary election held for the expression of a preference for the nomination of individuals for election to the office of President."],[0,"(2) The term \"candidate\" means an individual who seeks nomination for election, or election, to Federal office, and for purposes of this paragraph, an individual shall be deemed to seek nomination for election, or election—"],[1,"(A) if such individual has received contributions aggregating in excess of $5,000 or has made expenditures aggregating in excess of $5,000; or"],[1,"(B) if such individual has given his or her consent to another person to receive contributions or make expenditures on behalf of such individual and if such person has received such contributions aggregating in excess of $5,000 or has made such expenditures aggregating in excess of $5,000."],[0,"(3) The term \"Federal office\" means the office of President or Vice President, or of Senator or Representative in, or Delegate or Resident Commissioner to, the Congress."],[0,"(4) The term \"political committee\" means—"],[1,"(A) any committee, club, association, or other group of persons which receives contributions aggregating in excess of $1,000 during a calendar year or which makes expenditures aggregating in excess of $1,000 during a calendar year; or"],[1,"(B) any separate segregated fund established under the provisions of section 30118(b) of this title; or"],[1,"(C) any local committee of a political party which receives contributions aggregating in excess of $5,000 during a calendar year, or makes payments exempted from the definition of contribution or expenditure as defined in paragraphs (8) and (9) aggregating in excess of $5,000 during a calendar year, or makes contributions aggregating in excess of $1,000 during a calendar year or makes expenditures aggregating in excess of $1,000 during a calendar year."],[0,"(5) The term \"principal campaign committee\" means a political committee designated and authorized by a candidate under section 30102(e)(1) of this title."],[0,"(6) The term \"authorized committee\" means the principal campaign committee or any other political committee authorized by a candidate under section 30102(e)(1) of this title to receive contributions or make expenditures on behalf of such candidate."],[0,"(7) The term \"connected organization\" means any organization which is not a political committee but which directly or indirectly establishes, administers or financially supports a political committee."],[0,"(8)(A) The term \"contribution\" includes—"],[1,"(i) any gift, subscription, loan, advance, or deposit of money or anything of value made by any person for the purpose of influencing any election for Federal office; or"],[1,"(ii) the payment by any person of compensation for the personal services of another person which are rendered to a political committee without charge for any purpose."],[0,"(B) The term \"contribution\" does not include—"],[1,"(i) the value of services provided without compensation by any individual who volunteers on behalf of a candidate or political committee;"],[1,"(ii) the use of real or personal property, including a church or community room used on a regular basis by members of a community for noncommercial purposes, and the cost of invitations, food, and beverages, voluntarily provided by an individual to any candidate or any political committee of a political party in rendering voluntary personal services on the individual's residential premises or in the church or community room for candidate-related or political party-related activities, to the extent that the cumulative value of such invitations, food, and beverages provided by such individual on behalf of any single candidate does not exceed $1,000 with respect to any single election, and on behalf of all political committees of a political party does not exceed $2,000 in any calendar year;"],[1,"(iii) the sale of any food or beverage by a vendor for use in any candidate's campaign or for use by or on behalf of any political committee of a political party at a charge less than the normal comparable charge, if such charge is at least equal to the cost of such food or beverage to the vendor, to the extent that the cumulative value of such activity by such vendor on behalf of any single candidate does not exceed $1,000 with respect to any single election, and on behalf of all political committees of a political party does not exceed $2,000 in any calendar year;"],[1,"(iv) any unreimbursed payment for travel expenses made by any individual on behalf of any candidate or any political committee of a political party, to the extent that the cumulative value of such activity by such individual on behalf of any single candidate does not exceed $1,000 with respect to any single election, and on behalf of all political committees of a political party does not exceed $2,000 in any calendar year;"],[1,"(v) the payment by a State or local committee of a political party of the costs of preparation, display, or mailing or other distribution incurred by such committee with respect to a printed slate card or sample ballot, or other printed listing, of 3 or more candidates for any public office for which an election is held in the State in which such committee is organized, except that this clause shall not apply to any cost incurred by such committee with respect to a display of any such listing made on broadcasting stations, or in newspapers, magazines, or similar types of general public political advertising;"],[1,"(vi) any payment made or obligation incurred by a corporation or a labor organization which, under section 30118(b) of this title, would not constitute an expenditure by such corporation or labor organization;"],[1,"(vii) any loan of money by a State bank, a federally chartered depository institution, or a depository institution the deposits or accounts of which are insured by the Federal Deposit Insurance Corporation, Federal Savings and Loan Insurance Corporation, or the National Credit Union Administration, other than any overdraft made with respect to a checking or savings account, made in accordance with applicable law and in the ordinary course of business, but such loan—"],[2,"(I) shall be considered a loan by each endorser or guarantor, in that proportion of the unpaid balance that each endorser or guarantor bears to the total number of endorsers or guarantors;"],[2,"(II) shall be made on a basis which assures repayment, evidenced by a written instrument, and subject to a due date or amortization schedule; and"],[2,"(III) shall bear the usual and customary interest rate of the lending institution;"],[1,"(viii) any legal or accounting services rendered to or on behalf of—"],[2,"(I) any political committee of a political party if the person paying for such services is the regular employer of the person rendering such services and if such services are not attributable to activities which directly further the election of any designated candidate to Federal office; or"],[2,"(II) an authorized committee of a candidate or any other political committee, if the person paying for such services is the regular employer of the individual rendering such services and if such services are solely for the purpose of ensuring compliance with this Act or chapter 95 or chapter 96 of title 26,"],[1,"but amounts paid or incurred by the regular employer for such legal or accounting services shall be reported in accordance with section 30104(b) of this title by the committee receiving such services;"],[1,"(ix) the payment by a State or local committee of a political party of the costs of campaign materials (such as pins, bumper stickers, handbills, brochures, posters, party tabloids, and yard signs) used by such committee in connection with volunteer activities on behalf of nominees of such party: Provided, That—"],[2,"(1) such payments are not for the costs of campaign materials or activities used in connection with any broadcasting, newspaper, magazine, billboard, direct mail, or similar type of general public communication or political advertising;"],[2,"(2) such payments are made from contributions subject to the limitations and prohibitions of this Act; and"],[2,"(3) such payments are not made from contributions designated to be spent on behalf of a particular candidate or particular candidates;"],[1,"(x) the payment by a candidate, for nomination or election to any public office (including State or local office), or authorized committee of a candidate, of the costs of campaign materials which include information on or referenced to any other candidate and which are used in connection with volunteer activities (including pins, bumper stickers, handbills, brochures, posters, and yard signs, but not including the use of broadcasting, newspapers, magazines, billboards, direct mail, or similar types of general public communication or political advertising): Provided, That such payments are made from contributions subject to the limitations and prohibitions of this Act;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/30101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§30101. Definitions","tname":"Voting and Elections","by":{"1":"40"}},{"t":"reg","label":"68 Fed. Reg. 3970","url":"https://www.govinfo.gov/link/fr/68/3970","by":{"1":"13"}},{"t":"reg","label":"86 Fed. Reg. 7867","url":"https://www.govinfo.gov/link/fr/86/7867","by":{"1":"5"}},{"t":"case","label":"ABF Freight System, Inc. v. Teamsters","cite":"645 F.3d 954","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/645/954/","by":{"2":"9"}},{"t":"case","label":"Backer ex rel. Freedman v. Shah","cite":"788 F.3d 341","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/788/341/","by":{"2":"8"}},{"t":"case","label":"Bengzon v. Secretary of Justice","cite":"299 U.S. 410","y":1937,"id":"scdb/1936-135","sc":1,"sum":"1. An appropriation bill is one the primary and specific aim of which is to make appropriations of money from the public treasury.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Cameron County Housing Authority v. City of Port Isabel","cite":"997 F.3d 619","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/619/","by":{"2":"9"}},{"t":"case","label":"City of Los Angeles v. Patel","cite":"576 U.S. 409","y":2015,"id":"2014/13-1175","sc":1,"sum":"The Court determined that a municipal ordinance that allows the police to inspect hotel records without a warrant violates the Fourth Amendment’s prohibition against unreasonable searches unless the business owner is given the opportunity for pre-compliance review.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Finkelman v. National Football League","cite":"810 F.3d 187","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/810/187/","by":{"2":"8"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Garland v. Orlans, PC","cite":"999 F.3d 432","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/999/432/","by":{"2":"9"}},{"t":"case","label":"New York v. Ferber","cite":"458 U.S. 747","y":1982,"id":"1981/81-55","sc":1,"sum":"In the Court's first examination of a statute specifically targeted against child pornography, it found that the state's interest in preventing sexual exploitation of minors was a compelling \"government objective of surpassing importance.\" The law was carefully drawn to protect children from the mental, physical, and sexual abuse associated with pornography while not violating the First Amendment.","sumSrc":"Oyez","by":{"2":"20, 21"}},{"t":"case","label":"Parvati Corp. v. City of Oak Forest","cite":"630 F.3d 512","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/630/512/","by":{"2":"9"}},{"t":"case","label":"Petro-Chem Processing, Inc. v. EPA","cite":"866 F.2d 433","y":1989,"url":"https://www.courtlistener.com/c/F.2d/866/433/","by":{"2":"9"}},{"t":"case","label":"Skyline Wesleyan Church v. California Department of Managed Health Care","cite":"968 F.3d 738","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/968/738/","by":{"2":"9"}},{"t":"case","label":"Soon Hing v. Crowley","cite":"113 U.S. 703","y":1885,"id":"scdb/1884-166","sc":1,"sum":"The decision in Barbier v. Connelly, ante, 27 — that a municipal ordinance prohibiting from washing and ironing in public laundries and wash-houses within defined territorial limits, from ten o’clock at night to six in the morning, is a police regulation within the competency of a municipality possessed of ordinary powers — affirmed.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"State of Colorado v. U.S. EPA","cite":"989 F.3d 874","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/989/874/","op":2,"by":{"2":"9"}},{"t":"case","label":"United States v. O’Brien","cite":"391 U.S. 367","y":1968,"id":"1967/232","sc":1,"sum":"The Court found that it was not an infringement on one's First Amendment rights to criminalize burning a draft card.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Wagner v. FEC","cite":"793 F.3d 1","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/793/1/","by":{"2":"17"}},{"t":"case","label":"Washington State Grange v. Washington State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"sum":"The Court reversed the Ninth Circuit's ruling and held the party affiliation provision constitutional. Writing for the majority, Justice Clarence Thomas explained that the state law never referred to the candidates as nominees of any particular party.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"2":"5"}},{"t":"reg","label":"11 C.F.R. § 110.1","url":"https://www.ecfr.gov/current/title-11/section-110.1","subs":["(b)(6)"],"by":{"2":"4"}}]};